import { Router } from 'express';
import { getLlmBusinesses, getLlmsTxt } from '../controllers/llm.controller';
// Optional: If you want rate limiting, import express-rate-limit here.
import rateLimit from 'express-rate-limit';

const router = Router();

// Rate limit: 100 requests per 15 minutes by IP for the LLM ingest endpoint
const llmRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, 
  max: 100,
  message: { error: 'Too many requests from this IP for LLM ingest.' },
  standardHeaders: true,
  legacyHeaders: false,
});

// GET /api/v1/llm/businesses
router.get('/businesses', llmRateLimiter, getLlmBusinesses);

export default router;
